package com.circlenet.domain.privacy;
import java.security.Principal; import java.util.List; import org.springframework.http.ResponseEntity; import org.springframework.web.bind.annotation.*;
@RestController @RequestMapping("/api/privacy/blocks") public class PrivacyController {private final PrivacyService service;public PrivacyController(PrivacyService s){service=s;}public record BlockRequest(Long userId){}@GetMapping public List<PrivacyService.BlockedUser> list(Principal p){return service.list(id(p));}@PostMapping public PrivacyService.BlockedUser block(Principal p,@RequestBody BlockRequest r){return service.block(id(p),r.userId());}@DeleteMapping("/{userId}") public ResponseEntity<Void> unblock(Principal p,@PathVariable Long userId){service.unblock(id(p),userId);return ResponseEntity.noContent().build();}private Long id(Principal p){return Long.valueOf(p.getName());}}
